import sys

def main():
    data = sys.stdin.read().split()
    s, p = data[0], data[1]
    n, m = len(s), len(p)
    # prev[j]: does s[:i] match p[:j]
    prev = [False] * (m + 1)
    prev[0] = True
    for j in range(2, m + 1):
        if p[j - 1] == '*' and prev[j - 2]:
            prev[j] = True
    for i in range(1, n + 1):
        cur = [False] * (m + 1)
        c = s[i - 1]
        for j in range(1, m + 1):
            pc = p[j - 1]
            if pc == '*':
                q = p[j - 2]
                if cur[j - 2] or (prev[j] and (q == '.' or q == c)):
                    cur[j] = True
            elif prev[j - 1] and (pc == '.' or pc == c):
                cur[j] = True
        prev = cur
    print('true' if prev[m] else 'false')

main()

