        return toks
    def expand(toks):
        out = []
        for t in toks:
            if len(t) == 2:
                out.append(t[0] * rng.randint(0, 3))
            else:
                out.append(t[0])
        return ''.join(x if x != '.' else '' for x in out)
    def expand2(toks, alpha):
        out = []
        for t in toks:
            reps = rng.randint(0, 3) if len(t) == 2 else 1
            for _ in range(reps):
                out.append(rng.choice(alpha) if t[0] == '.' else t[0])
